    history = acquire("history")
    if not history:
        return {"value": None, "unresolved": True}

    goal = context.get("goal", "channel")
    actions = context.get("actions", [])

    def simulate_full(seq_actions, strat, trig, chan_mode):
        committed = {}
        m_pend = {}
        o_pend = {}

        m_tot = 0
        o_tot = 0
        m_last = 0

        m_open = False
        o_open = False

        for act in seq_actions:
            op = act['op']
            c = act.get('connection', 'main')
            k = act.get('key')
            v = act.get('value')

            if op == 'begin':
                if c == 'main': 
                    m_open = True
                    m_pend = {}
                else: 
                    o_open = True
                    o_pend = {}
            elif op == 'commit':
                if c == 'main':
                    for pk, pv in m_pend.items():
                        if pv is None: 
                            if pk in committed: del committed[pk]
                        else: 
                            committed[pk] = pv
                    m_pend = {}
                    m_open = False
                else:
                    for pk, pv in o_pend.items():
                        if pv is None: 
                            if pk in committed: del committed[pk]
                        else: 
                            committed[pk] = pv
                    o_pend = {}
                    o_open = False
            elif op == 'rollback':
                if c == 'main': 
                    m_pend = {}
                    m_open = False
